CREATE SCHEMA payment;
GRANT USAGE ON SCHEMA "payment" TO zp_execution;
GRANT USAGE ON SCHEMA "payment" TO zp_relay;

CREATE TABLE "payment"."idempotency_registry" (
    environment         text        NOT NULL CHECK (environment IN ('TEST','LIVE')),
    cell_id             text        NOT NULL,
    legal_entity_id     text        NOT NULL,
    tenant_id           text        NOT NULL,
    merchant_id         text        NOT NULL,
    client_id           text        NOT NULL,
    principal_id        text        NOT NULL,
    api_major           integer     NOT NULL CHECK (api_major > 0),
    method              text        NOT NULL,
    route_template      text        NOT NULL,
    operation_kind      text        NOT NULL,
    key_digest          bytea       NOT NULL CHECK (octet_length(key_digest) = 32),
    fingerprint_version text        NOT NULL,
    request_fingerprint bytea       NOT NULL CHECK (octet_length(request_fingerprint) = 32),
    operation_id        text        NOT NULL UNIQUE,
    status              text        NOT NULL CHECK (status IN ('IN_PROGRESS','COMPLETED')),
    response_status     integer     NULL CHECK (response_status BETWEEN 100 AND 599),
    resource_id         text        NULL,
    created_at_utc      timestamptz NOT NULL,
    last_seen_at_utc    timestamptz NOT NULL,
    PRIMARY KEY (environment, cell_id, legal_entity_id, tenant_id, merchant_id, client_id, principal_id,
                 api_major, method, route_template, operation_kind, key_digest),
    CHECK ((status = 'COMPLETED') = (response_status IS NOT NULL))
);
CREATE FUNCTION "payment"."zp_idempotency_guard"() RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
    IF TG_OP IN ('DELETE', 'TRUNCATE') THEN
        RAISE EXCEPTION 'idempotency identities are never deleted (04-08 §6.2)' USING ERRCODE = 'restrict_violation';
    END IF;
    IF (NEW.environment, NEW.cell_id, NEW.legal_entity_id, NEW.tenant_id, NEW.merchant_id, NEW.client_id,
        NEW.principal_id, NEW.api_major, NEW.method, NEW.route_template, NEW.operation_kind, NEW.key_digest,
        NEW.fingerprint_version, NEW.request_fingerprint, NEW.operation_id, NEW.created_at_utc)
       IS DISTINCT FROM
       (OLD.environment, OLD.cell_id, OLD.legal_entity_id, OLD.tenant_id, OLD.merchant_id, OLD.client_id,
        OLD.principal_id, OLD.api_major, OLD.method, OLD.route_template, OLD.operation_kind, OLD.key_digest,
        OLD.fingerprint_version, OLD.request_fingerprint, OLD.operation_id, OLD.created_at_utc) THEN
        RAISE EXCEPTION 'an idempotency identity cannot change' USING ERRCODE = 'restrict_violation';
    END IF;
    IF OLD.status = 'COMPLETED' AND (NEW.status, NEW.response_status, NEW.resource_id)
       IS DISTINCT FROM (OLD.status, OLD.response_status, OLD.resource_id) THEN
        RAISE EXCEPTION 'a completed idempotency result cannot change' USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER idempotency_guard BEFORE UPDATE OR DELETE ON "payment"."idempotency_registry" FOR EACH ROW EXECUTE FUNCTION "payment"."zp_idempotency_guard"();
CREATE TRIGGER idempotency_guard_truncate BEFORE TRUNCATE ON "payment"."idempotency_registry" FOR EACH STATEMENT EXECUTE FUNCTION "payment"."zp_idempotency_guard"();
ALTER TABLE "payment"."idempotency_registry" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "payment"."idempotency_registry" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "payment"."idempotency_registry"
    USING (tenant_id = current_setting('zp.tenant_id', true))
    WITH CHECK (tenant_id = current_setting('zp.tenant_id', true));

GRANT SELECT, INSERT ON "payment"."idempotency_registry" TO zp_execution;
GRANT UPDATE (status, response_status, resource_id, last_seen_at_utc) ON "payment"."idempotency_registry" TO zp_execution;

CREATE TABLE "payment"."outbox_events" (
    event_id            uuid        PRIMARY KEY CHECK (uuid_extract_version(event_id) = 7),
    source              text        NOT NULL,
    tenant_id           text        NOT NULL,
    cell_id             text        NOT NULL,
    legal_entity_id     text        NOT NULL,
    aggregate_id        text        NOT NULL,
    aggregate_version   bigint      NOT NULL CHECK (aggregate_version > 0),
    event_type          text        NOT NULL,
    dataschema          text        NOT NULL,
    envelope            bytea       NOT NULL,
    payload_sha256      text        NOT NULL CHECK (payload_sha256 ~ '^[0-9a-f]{64}$'),
    created_at_utc      timestamptz NOT NULL,
    published_at_utc    timestamptz NULL,
    attempts            integer     NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    next_attempt_at_utc timestamptz NOT NULL,
    last_error          text        NULL,
    parked_at_utc       timestamptz NULL,
    park_reason         text        NULL,
    UNIQUE (source, aggregate_id, aggregate_version, event_type),
    CHECK (published_at_utc IS NULL OR parked_at_utc IS NULL)
);
CREATE INDEX outbox_due ON "payment"."outbox_events" (next_attempt_at_utc, created_at_utc) WHERE published_at_utc IS NULL AND parked_at_utc IS NULL;
CREATE INDEX outbox_unpublished_by_aggregate ON "payment"."outbox_events" (source, aggregate_id, aggregate_version) WHERE published_at_utc IS NULL;
CREATE INDEX outbox_parked ON "payment"."outbox_events" (parked_at_utc) WHERE parked_at_utc IS NOT NULL;
CREATE TABLE "payment"."outbox_requeue_log" (
    requeue_id        uuid        PRIMARY KEY CHECK (uuid_extract_version(requeue_id) = 7),
    event_id          uuid        NOT NULL REFERENCES "payment"."outbox_events" (event_id),
    requeued_by       text        NOT NULL CHECK (requeued_by <> ''),
    reason            text        NOT NULL CHECK (length(reason) >= 10),
    attempts_before   integer     NOT NULL,
    last_error_before text        NULL,
    park_reason_before text       NULL,
    requeued_at_utc   timestamptz NOT NULL
);
CREATE FUNCTION "payment"."zp_outbox_guard"() RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog AS $$
BEGIN
    IF TG_OP IN ('DELETE', 'TRUNCATE') THEN
        RAISE EXCEPTION '% rows are never deleted', TG_TABLE_NAME USING ERRCODE = 'restrict_violation';
    END IF;
    IF TG_TABLE_NAME = 'outbox_requeue_log' THEN
        RAISE EXCEPTION 'the requeue log is append-only' USING ERRCODE = 'restrict_violation';
    END IF;
    IF (NEW.event_id, NEW.source, NEW.tenant_id, NEW.cell_id, NEW.legal_entity_id, NEW.aggregate_id,
        NEW.aggregate_version, NEW.event_type, NEW.dataschema, NEW.envelope, NEW.payload_sha256, NEW.created_at_utc)
       IS DISTINCT FROM
       (OLD.event_id, OLD.source, OLD.tenant_id, OLD.cell_id, OLD.legal_entity_id, OLD.aggregate_id,
        OLD.aggregate_version, OLD.event_type, OLD.dataschema, OLD.envelope, OLD.payload_sha256, OLD.created_at_utc) THEN
        RAISE EXCEPTION 'a stored event cannot change' USING ERRCODE = 'restrict_violation';
    END IF;
    IF OLD.published_at_utc IS NOT NULL AND NEW.published_at_utc IS DISTINCT FROM OLD.published_at_utc THEN
        RAISE EXCEPTION 'a published event cannot be unpublished' USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER outbox_guard BEFORE UPDATE OR DELETE ON "payment"."outbox_events" FOR EACH ROW EXECUTE FUNCTION "payment"."zp_outbox_guard"();
CREATE TRIGGER outbox_guard_truncate BEFORE TRUNCATE ON "payment"."outbox_events" FOR EACH STATEMENT EXECUTE FUNCTION "payment"."zp_outbox_guard"();
